<script setup lang="ts">import { onBeforeUnmount,onMounted,useTemplateRef } from "vue";import { ChevronDown,Info } from "lucide-vue-next";import AceiteChangeSummary from "./AceiteChangeSummary.vue";import { formatNumber } from "@/stores/dbequipos/engrase/catalogo/aceitesCatalogo.helpers";import type { CatalogoAceiteGuardarInput,CatalogoAceiteItem } from "@/stores/dbequipos/engrase/catalogo/aceitesCatalogo.types";defineProps<{original:CatalogoAceiteItem;draft:CatalogoAceiteGuardarInput;saving:boolean}>();const emit=defineEmits<{cancel:[];confirm:[]}>();const dialogRef=useTemplateRef<HTMLElement>("dialog");let previousFocus:HTMLElement|null=null;function keydown(event:KeyboardEvent){if(event.key==="Escape"){event.preventDefault();emit("cancel");return}if(event.key!=="Tab"||!dialogRef.value)return;const controls=Array.from(dialogRef.value.querySelectorAll<HTMLElement>('button:not([disabled]), summary'));const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}onMounted(()=>{previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;window.addEventListener("keydown",keydown);requestAnimationFrame(()=>dialogRef.value?.querySelector<HTMLElement>("button")?.focus())});onBeforeUnmount(()=>{window.removeEventListener("keydown",keydown);previousFocus?.focus()});</script>
<template><Teleport to="body"><div class="fixed inset-0 z-[80] grid place-items-center bg-main-dark/55 p-4" @click.self="!saving&&emit('cancel')"><section ref="dialog" role="dialog" aria-modal="true" aria-labelledby="oil-confirm-title" :aria-busy="saving" class="max-h-[calc(100dvh-2rem)] w-full max-w-[540px] overflow-y-auto rounded-xl bg-white shadow-2xl"><header class="border-b border-gray-200 p-4"><h2 id="oil-confirm-title" class="text-base font-bold text-main">Confirmar actualización</h2></header><div class="space-y-5 p-4"><div class="flex gap-3 rounded-md border border-main/25 bg-main/5 p-3 text-sm text-main"><Info class="mt-0.5 h-4 w-4 shrink-0" /><p>Esta actualización se reflejará en <strong>{{formatNumber(original.impacto.totalEquipos)}} {{original.impacto.totalEquipos===1?'equipo':'equipos'}}</strong>.</p></div><AceiteChangeSummary :original="original" :draft="draft" /><details class="group overflow-hidden rounded-md border border-gray-200 bg-white"><summary class="flex min-h-11 cursor-pointer list-none items-center justify-between gap-3 px-3 text-xs font-semibold text-gray-800 outline-none hover:bg-gray-50 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-main [&::-webkit-details-marker]:hidden"><span>Resumen de equipos</span><span class="inline-flex items-center gap-2 text-main"><span class="tabular-nums">{{formatNumber(original.impacto.totalEquipos)}}</span><ChevronDown class="h-4 w-4 transition-transform group-open:rotate-180 motion-reduce:transition-none" aria-hidden="true" /></span></summary><dl class="space-y-1.5 border-t border-gray-200 p-3 text-xs"><div v-for="item in [...original.impacto.tiposEquipo].sort((a,b)=>b.cantidadEquipos-a.cantidadEquipos)" :key="item.id" class="flex justify-between gap-4"><dt>{{item.nombre}}</dt><dd>{{formatNumber(item.cantidadEquipos)}}</dd></div><div class="flex justify-between border-t border-gray-200 pt-2 font-semibold"><dt>Total asignaciones</dt><dd>{{formatNumber(original.impacto.totalAsignaciones)}}</dd></div></dl></details><div class="flex gap-3 rounded-md border border-main/25 bg-main/5 p-3 text-xs leading-5 text-main"><Info class="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" /><p>Solo se actualizarán los datos del catálogo.<br />Los sistemas y las asociaciones con equipos no se modificarán.</p></div></div><footer class="grid gap-2 border-t border-gray-200 p-4 sm:grid-cols-2"><button class="min-h-11 rounded-md border border-gray-300 text-sm font-semibold" :class="saving?'cursor-not-allowed opacity-50':'cursor-pointer'" :disabled="saving" @click="emit('cancel')">Cancelar</button><button class="inline-flex min-h-11 items-center justify-center rounded-md bg-main text-sm font-semibold text-white" :class="saving?'cursor-wait opacity-70':'cursor-pointer hover:bg-main-light'" :disabled="saving" @click="emit('confirm')"><span v-if="saving" class="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />{{saving?'Guardando…':'Confirmar y guardar'}}</button></footer></section></div></Teleport></template>
